function rememberedMobile(){try{const number=localStorage.getItem('dailytally-last-phone')||'';return /^01[3-9]\d{8}$/.test(number)?number:''}catch{return ''}}
function rememberMobile(number){if(/^01[3-9]\d{8}$/.test(number))try{localStorage.setItem('dailytally-last-phone',number)}catch{}}
function deviceLoginPreference(){try{const value=JSON.parse(localStorage.getItem('dailytally-device-login')||'null');return value&&/^01[3-9]\d{8}$/.test(value.phone)&&typeof value.id==='string'?value:null}catch{return null}}
function deviceAccessIcon(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 3H5a2 2 0 0 0-2 2v3m13-5h3a2 2 0 0 1 2 2v3M3 16v3a2 2 0 0 0 2 2h3m8 0h3a2 2 0 0 0 2-2v-3M8 10a4 4 0 0 1 8 0v3m-10 0v-3a6 6 0 0 1 12 0v4m-8-4a2 2 0 0 1 4 0v4a6 6 0 0 1-2 4m-4-5a6 6 0 0 1-1 4m5-5v2"/></svg>'}
async function deviceAccessAvailable(){if(nativeAuthPresent())return !!(await nativeAuthCall("available",{})).available;try{return !!(globalThis.isSecureContext&&globalThis.PublicKeyCredential&&navigator.credentials&&await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable())}catch{return false}}
function passkeyBytes(value){return Uint8Array.from(atob(value.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0))}
function passkeyBase64(value){return btoa(String.fromCharCode(...new Uint8Array(value))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,'')}
function credentialJSON(credential){const r=credential.response,response={clientDataJSON:passkeyBase64(r.clientDataJSON)};if(r.attestationObject){response.attestationObject=passkeyBase64(r.attestationObject);response.transports=r.getTransports?.()||[]}else{response.authenticatorData=passkeyBase64(r.authenticatorData);response.signature=passkeyBase64(r.signature);response.userHandle=r.userHandle?passkeyBase64(r.userHandle):null}return {id:credential.id,rawId:passkeyBase64(credential.rawId),type:credential.type,response,clientExtensionResults:credential.getClientExtensionResults(),authenticatorAttachment:credential.authenticatorAttachment}}
function restoreMobileField(register){const input=document.querySelector('#auth-phone');if(!input)return;input.autocomplete=register?'tel':'username';input.setAttribute('pattern','(?:\\+?880|0)1[3-9][0-9]{8}');if(register)return;input.value=rememberedMobile();const correct=()=>{if(input.value.includes('@'))input.value=rememberedMobile()};input.addEventListener('change',correct);input.addEventListener('input',correct);for(const delay of [100,600,1500])setTimeout(()=>{if(input.isConnected)correct()},delay)}
function openLanguageSettings(){const d=featureDialog('ভাষা','<div class="device-settings-intro"><span class="device-access-emblem">◎</span><h3>আপনার ভাষা বাছুন</h3></div><div class="language-options"><button type="button" data-language="en"><strong>English</strong><span>English</span></button><button type="button" data-language="bn"><strong>বাংলা</strong><span>বাংলা</span></button></div>');d.querySelectorAll('[data-language]').forEach(button=>{button.setAttribute('aria-pressed',String(button.dataset.language===uiLanguage));button.onclick=()=>{setUILanguage(button.dataset.language);d.close();render()}})}
async function openDeviceAccessSettings(){const preference=deviceLoginPreference(),enabled=preference?.phone===accountPhone;
 const native=nativeAuthPresent();const d=featureDialog('ডিভাইস দিয়ে লগইন','<div class="device-settings-intro"><span class="device-access-emblem">'+deviceAccessIcon()+'</span><h3>আপনার ডিভাইস, আপনার নিরাপত্তা</h3><p>'+featureText(native?'ফোনের ফিঙ্গারপ্রিন্ট বা নিরাপদ স্ক্রিন লক দিয়ে লগইন করুন।':'Face ID, Touch ID, fingerprint অথবা device PIN দিয়ে যাচাই করে লগইন করুন।')+'</p></div><p class="device-access-note">'+featureText(native?'ইন্টারনেট প্রয়োজন। আপনার ফিঙ্গারপ্রিন্ট অ্যাপে বা সার্ভারে সংরক্ষিত হয় না।':'ইন্টারনেট ও সমর্থিত ব্রাউজার প্রয়োজন। আপনার বায়োমেট্রিক তথ্য অ্যাপে সংরক্ষিত হয় না।')+'</p><form id="device-access-form">'+(!enabled?'<label>বর্তমান পাসওয়ার্ড<input name="password" type="password" autocomplete="current-password" required></label>':'')+'<p class="danger" role="alert" id="device-access-error"></p><button class="primary" type="submit">'+(enabled?'এই ডিভাইসে বন্ধ করুন':'এই ডিভাইসে চালু করুন')+'</button></form>');
 d.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=d.querySelector('button[type="submit"]'),error=d.querySelector('#device-access-error');button.disabled=true;error.textContent='';try{
  if(enabled){await accountAPI(preference.mode==='android'?'native-auth/remove':'passkeys/remove','POST',{id:preference.id});if(preference.mode==='android'&&nativeAuthPresent())await nativeAuthCall('remove',{keyId:preference.id});localStorage.removeItem('dailytally-device-login');d.close();render();return}
  if(!await deviceAccessAvailable())throw Error(native?nativeAuthError('Set up fingerprint or a secure screen lock in your phone settings, then try again.'):featureText('এই ডিভাইস বা ব্রাউজারে সুবিধাটি নেই। সমর্থিত ব্রাউজারে অ্যাপটি খুলুন।'));
  const password=event.target.elements.password.value;if(nativeAuthPresent()){await enrollNativeDevice(password);event.target.reset();d.close();render();return}const request=await accountAPI('passkeys/register/options','POST',{password});event.target.reset();const options=request.options;options.challenge=passkeyBytes(options.challenge);options.user.id=passkeyBytes(options.user.id);options.excludeCredentials=options.excludeCredentials.map(c=>({...c,id:passkeyBytes(c.id)}));const credential=await navigator.credentials.create({publicKey:options});if(!credential)throw Error();const result=await accountAPI('passkeys/register/verify','POST',{id:request.id,response:credentialJSON(credential)});localStorage.setItem('dailytally-device-login',JSON.stringify({id:result.id,phone:result.phone}));rememberMobile(result.phone);d.close();render();alert('ডিভাইস দিয়ে লগইন চালু হয়েছে। পরের বার অ্যাপ খুললে ডিভাইস যাচাই করুন।');
 }catch(e){error.textContent=e.name==='NotAllowedError'?featureText('যাচাই বাতিল হয়েছে। আবার চেষ্টা করুন।'):e.message||featureText('ডিভাইস যাচাই হয়নি। আবার চেষ্টা করুন।');button.disabled=false}};
}
async function signInWithDevice(button){const pref=deviceLoginPreference();if(!pref)return;const error=document.querySelector('#auth-error');button.disabled=true;if(error)error.textContent='';try{if(pref.mode==='android'){if(!nativeAuthPresent())throw Error(nativeAuthError('Open the Android app to use this device key.'));const request=await accountAPI('native-auth/login/options','POST',{phone:pref.phone,credentialId:pref.id});const proof=await nativeAuthCall('login',request);await accountAPI('native-auth/login/verify','POST',{id:request.id,signature:proof.signature});await loadAccount();return}if(!await deviceAccessAvailable())throw Error(featureText('এই ডিভাইস বা ব্রাউজারে সুবিধাটি নেই। সমর্থিত ব্রাউজারে অ্যাপটি খুলুন।'));const request=await accountAPI('passkeys/login/options','POST',{phone:pref.phone,credentialId:pref.id}),options=request.options;options.challenge=passkeyBytes(options.challenge);options.allowCredentials=options.allowCredentials.map(c=>({...c,id:passkeyBytes(c.id)}));const credential=await navigator.credentials.get({publicKey:options});if(!credential)throw Error();await accountAPI('passkeys/login/verify','POST',{id:request.id,response:credentialJSON(credential)});await loadAccount()}catch(e){if(error)error.textContent=e.name==='NotAllowedError'?featureText('যাচাই বাতিল হয়েছে। পাসওয়ার্ড দিয়েও লগইন করতে পারবেন।'):e.message||featureText('ডিভাইস যাচাই হয়নি। আবার চেষ্টা করুন।')}finally{button.disabled=false}}
function addDeviceSignIn(register){if(register||!deviceLoginPreference())return;const form=document.querySelector('#auth-form');if(!form)return;const button=document.createElement('button');button.type='button';button.className='device-signin';button.innerHTML=deviceAccessIcon()+'<span>ডিভাইস দিয়ে লগইন</span>';button.onclick=()=>void signInWithDevice(button);form.append(button)}

function nativeAuthPresent(){return typeof window!=='undefined'&&typeof window.DailyTallyFiles?.nativeAuth==='function'}
function nativeAuthCall(operation,input){
 if(!nativeAuthPresent())return Promise.reject(Error(nativeAuthError('Open the Android app to use this device key.')));
 if(!window.DailyTallyNativeAuth){const pending=new Map();window.DailyTallyNativeAuth={pending,receive(id,result){const item=pending.get(id);if(!item)return;pending.delete(id);clearTimeout(item.timer);result.error?item.reject(Error(nativeAuthError(result.error))):item.resolve(result)}}}
 return new Promise((resolve,reject)=>{const id=crypto.randomUUID(),pending=window.DailyTallyNativeAuth.pending,timer=setTimeout(()=>{pending.delete(id);reject(Error(nativeAuthError('Device verification failed. Please try again.')))},180000);pending.set(id,{resolve,reject,timer});try{window.DailyTallyFiles.nativeAuth(id,operation,JSON.stringify(input))}catch(error){clearTimeout(timer);pending.delete(id);reject(error)}});
}
function nativeAuthError(message){const bn={
 'Open the Android app to use this device key.':'এই ডিভাইস কী ব্যবহার করতে Android অ্যাপটি খুলুন।',
 'Set up fingerprint or a secure screen lock in your phone settings, then try again.':'ফোনের সেটিংসে ফিঙ্গারপ্রিন্ট বা নিরাপদ স্ক্রিন লক চালু করে আবার চেষ্টা করুন।',
 'Device verification failed. Please sign in with your password and enable it again.':'ডিভাইস যাচাই হয়নি। পাসওয়ার্ড দিয়ে লগইন করে আবার চালু করুন।',
 'Verification cancelled. You can sign in with your password.':'যাচাই বাতিল হয়েছে। পাসওয়ার্ড দিয়েও লগইন করতে পারবেন।',
 'Device verification is unavailable. Check your phone security settings and try again.':'ডিভাইস যাচাই চালু নেই। ফোনের নিরাপত্তা সেটিংস দেখে আবার চেষ্টা করুন।',
 'Device key is unavailable. Sign in with your password and enable device login again.':'ডিভাইস কী পাওয়া যায়নি। পাসওয়ার্ড দিয়ে লগইন করে ডিভাইস লগইন আবার চালু করুন।',
 'Google sign-in failed. Please try again.':'Google লগইন হয়নি। আবার চেষ্টা করুন।',
 'Google sign-in was cancelled or is unavailable. Check Google Play services and the Android OAuth configuration, then try again.':'Google লগইন বাতিল হয়েছে বা চালু নেই। Google Play services ও Android OAuth সেটআপ পরীক্ষা করে আবার চেষ্টা করুন।',
 'Google sign-in is unavailable. Please try again.':'Google লগইন চালু নেই। আবার চেষ্টা করুন।',
 'Finish the current verification first.':'আগের যাচাইটি আগে শেষ করুন।',
 'Device verification failed. Please try again.':'ডিভাইস যাচাই হয়নি। আবার চেষ্টা করুন।'
 };return typeof uiLanguage!=='undefined'&&uiLanguage==='bn'?(bn[message]||message):message;
}
async function enrollNativeDevice(password){
 const request=await accountAPI('native-auth/register/options','POST',{password});let saved=false;
 try{const proof=await nativeAuthCall('register',request),result=await accountAPI('native-auth/register/verify','POST',{id:request.id,publicKey:proof.publicKey,signature:proof.signature});saved=true;localStorage.setItem('dailytally-device-login',JSON.stringify({id:result.id,phone:result.phone,mode:'android'}));rememberMobile(result.phone)}
 finally{if(!saved)try{await nativeAuthCall('remove',{keyId:request.keyId})}catch{}}
}
async function nativeGoogleSignIn(button){
 button.disabled=true;const error=document.querySelector('#auth-error');if(error)error.textContent='';
 try{const request=await accountAPI('native-auth/google/options','POST',{}),result=await nativeAuthCall('google',request),verified=await accountAPI('native-auth/google/verify','POST',{id:request.id,token:result.token});if(verified.complete){history.replaceState(null,'',location.pathname+'?social=complete');authScreen()}else{localStorage.removeItem('dailytally-locked');await loadAccount()}}
 catch(failure){if(error)error.textContent=failure.message}finally{button.disabled=false}
}
